def adddeps(t,ids):
 a=t.index('deps:\n')+len('deps:\n');b=re.search(r'^\S',t[a:],re.M).start()+a
 for id in ids:
  if not re.search(r'^  - '+re.escape(id)+r'$',t[a:b],re.M):t=t[:b]+'  - '+id+'\n'+t[b:];b+=len('  - '+id+'\n')
 return t
def fact(t,n,new):return re.sub(r'^\[F'+str(n)+r'\].*?(?=\n\n)',lambda _:new,t,count=1,flags=re.M|re.S)
def step(t,n,new):return re.sub(r'^'+re.escape(n)+r' .*?(?=\n\n\d+\.\d+ |\n\n## |\Z)',lambda _:new+'\n',t,count=1,flags=re.M|re.S)
